command_executions.command:
cd /workspace && echo "--- health_check ---"; curl -s -o /dev/null -w "%{http_code}
" http://localhost:8080/health_check; echo "--- /api/v3/configuration ---"; curl -s -o /dev/null -w "%{http_code}
" http://localhost:8080/api/v3/configuration; echo "--- login page with session+csrf retry ---"; rm -f /tmp/cj2.txt; curl -s -c /tmp/cj2.txt http://localhost:8080/login -o /tmp/l2.html; T=$(grep -o 'name="authenticity_token" value="[^"]*"' /tmp/l2.html | head -1 | sed 's/.*value="//;s/"//'); curl -s -b /tmp/cj2.txt -c /tmp/cj2.txt -o /dev/null -w "login(admin/admin) => %{http_code}
" -X POST http://localhost:8080/login --data-urlencode "authenticity_token=$T" --data-urlencode "username=admin" --data-urlencode "password=admin"; echo "--- whoami after login ---"; curl -s -b /tmp/cj2.txt http://localhost:8080/api/v3/users/me -o /dev/null -w "%{http_code}
"
